// spec: .qa/e2e/specs/tender-actions.md
// seed: tests/seed.company.spec.ts
import { test, expect, Page } from '@playwright/test';
import path from 'path';
import { fillFreeTenderWizardToTerms, publishFromTerms, expectNoPayment, journal } from '../_helpers/tender-wizard';

test.use({ storageState: path.join(__dirname, '../../../auth/company.json') });
// Steps depend on each other (one QA-AUTO tender goes through edit → extend → close → archive).
test.describe.configure({ mode: 'serial' });

const fmt = (d: Date) => `${String(d.getDate()).padStart(2, '0')}.${String(d.getMonth() + 1).padStart(2, '0')}.${d.getFullYear()}`;
const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

test.describe('Tender owner actions (company)', () => {
  test('Edit, extend, close with confirmation and archive own tender @desktop @data #cf6dc1', async ({ page }) => {
    test.setTimeout(240_000);
    const title = `QA-AUTO-cf6dc1-${Date.now()}`;
    const edited = `${title} edited`;
    let tenderId: string | undefined;
    let published = false;
    let archived = false;

    const myCard = (name: string) =>
      page.getByRole('listitem').filter({ has: page.getByRole('heading', { level: 3, name, exact: true }) });
    const openMenuOnCard = async (name: string) => {
      await myCard(name).getByRole('button', { name: 'פעולות מכרז' }).click();
    };
    const openTender = async (p: Page) => {
      await p.goto(`/tenders/${tenderId}`);
      const d = p.getByRole('dialog', { name: 'פרטי המכרז' });
      await expect(d).toBeVisible();
      return d;
    };

    try {
      // 1. Create a free regular tender and publish it
      await test.step('1. publish a free QA-AUTO tender', async () => {
        tenderId = await fillFreeTenderWizardToTerms(page, title, 'QA-AUTO — מכרז בדיקה, נא לא להגיש הצעות');
        test.info().annotations.push({ type: 'qa-auto-data', description: `tender ${tenderId} «${title}»` });
        await publishFromTerms(page);
        published = true;
        // control for step 6: the active tender is found by the keyword search in «כל המכרזים»
        await page.goto(`/tenders?q=${encodeURIComponent(title)}`);
        await expect(page.getByRole('heading', { level: 3, name: title, exact: true })).toBeVisible();
      });

      // 2. Edit the title
      await test.step('2. «עריכת מכרז» — new title', async () => {
        await page.goto('/tenders?mine=1');
        await openMenuOnCard(title);
        await page.getByRole('menuitem', { name: 'עריכת מכרז' }).click();
        const dlg = page.getByRole('dialog', { name: 'עריכת מכרז' });
        await dlg.getByRole('textbox', { name: /^כותרת המכרז/ }).fill(edited);
        await dlg.getByRole('button', { name: 'שמירה' }).click();
        await expect(dlg).toBeHidden();
        // Expected: the card and the tender page show the new title
        await expect(myCard(edited)).toHaveCount(1);
        const d = await openTender(page);
        await expect(d.getByRole('heading', { level: 3, name: edited, exact: true })).toBeVisible();
      });

      // 3. Extend by 14 days, regular (free)
      await test.step('3. «הארכת המכרז» +14 days, «מכרז רגיל — ללא עלות»', async () => {
        await page.goto('/tenders?mine=1');
        await openMenuOnCard(edited);
        await page.getByRole('menuitem', { name: 'הארכת המכרז' }).click();
        const dlg = page.getByRole('dialog', { name: 'הארכת המכרז' });
        const activeUntil = (await dlg.getByText(/^המכרז פעיל עד \d{2}\.\d{2}\.\d{4}$/).innerText()).match(/(\d{2})\.(\d{2})\.(\d{4})/)!;
        const newDate = new Date(Number(activeUntil[3]), Number(activeUntil[2]) - 1, Number(activeUntil[1]) + 14);
        await dlg.getByRole('textbox', { name: /^תאריך תוקף חדש/ }).fill(iso(newDate));
        await expect(dlg.getByRole('radio', { name: 'מכרז רגיל ללא עלות' })).toBeChecked();
        await dlg.getByRole('button', { name: 'אישור' }).click();
        await expect(dlg).toBeHidden();
        // Expected: «תאריך תוקף» on the card = the new date; no payment window
        await expectNoPayment(page);
        await expect(myCard(edited)).toContainText(new RegExp(`תאריך תוקף\\s*${fmt(newDate).replace(/\./g, '\\.')}`));
      });

      // 4. Close → «ביטול»
      await test.step('4. «סגירת מכרז» → «ביטול»', async () => {
        await openMenuOnCard(edited);
        await page.getByRole('menuitem', { name: 'סגירת מכרז' }).click();
        const dlg = page.getByRole('dialog', { name: 'לסגור את המכרז?' });
        await expect(dlg).toContainText('המכרז יוסר מרשימת המכרזים ולא יתקבלו בו הצעות נוספות');
        await dlg.getByRole('button', { name: 'ביטול' }).click();
        await expect(dlg).toBeHidden();
        // Expected: still «פעיל»
        await expect(myCard(edited).getByText('פעיל', { exact: true })).toBeVisible();
      });

      // 5. Close → «סגירת המכרז»
      await test.step('5. «סגירת מכרז» → «סגירת המכרז»', async () => {
        await openMenuOnCard(edited);
        await page.getByRole('menuitem', { name: 'סגירת מכרז' }).click();
        const dlg = page.getByRole('dialog', { name: 'לסגור את המכרז?' });
        await dlg.getByRole('button', { name: 'סגירת המכרז' }).click();
        await expect(dlg).toBeHidden();
        // Expected: badge «סגור», «המכרז סגור ואינו מקבל הצעות.», the «•••» menu has only «העברה לארכיון»
        await expect(myCard(edited).getByText('סגור', { exact: true })).toBeVisible();
        const d = await openTender(page);
        await expect(d.getByText('סגור', { exact: true })).toBeVisible();
        await expect(d.getByText('המכרז סגור ואינו מקבל הצעות.')).toBeVisible();
        await d.getByRole('button', { name: 'פעולות מכרז' }).click();
        await expect(page.getByRole('menuitem')).toHaveText(['העברה לארכיון']);
        await page.keyboard.press('Escape');
      });

      // 6. «כל המכרזים» — keyword search
      await test.step('6. closed tender is not in «כל המכרזים»', async () => {
        await page.goto(`/tenders?q=${encodeURIComponent(title)}`);
        await expect(page.getByRole('main').getByRole('status')).toHaveText('0 תוצאות');
        await expect(page.getByRole('heading', { level: 3, name: edited, exact: true })).toHaveCount(0);
      });

      // 7. Archive from the tender page
      await test.step('7. «העברה לארכיון» → confirm', async () => {
        const d = await openTender(page);
        await d.getByRole('button', { name: 'פעולות מכרז' }).click();
        await page.getByRole('menuitem', { name: 'העברה לארכיון' }).click();
        const dlg = page.getByRole('dialog', { name: 'להעביר את המכרז לארכיון?' });
        await dlg.getByRole('button', { name: 'העברה לארכיון' }).click();
        await expect(dlg).toBeHidden();
        await expect(d.getByText('בארכיון', { exact: true })).toBeVisible();
        archived = true;
      });

      // 8. «ארכיון»
      await test.step('8. «מכרזים בארכיון» lists it, «המכרזים שלי» does not', async () => {
        await page.goto('/tenders?mine=1');
        await expect(myCard(edited)).toHaveCount(0);
        await page.getByRole('link', { name: 'ארכיון', exact: true }).click();
        await expect(page).toHaveURL(/archive=1/);
        await expect(page.getByRole('heading', { level: 1, name: 'מכרזים בארכיון' })).toBeVisible();
        await expect(myCard(edited)).toHaveCount(1);
        await expect(myCard(edited).getByText('בארכיון', { exact: true })).toBeVisible();
      });
    } finally {
      // 9. Cleanup: if a step failed before archiving — archive the tender via the menu (archiving also closes it)
      if (tenderId && !archived) {
        try {
          if (!published) throw new Error('not published — stays a draft');
          const d = await openTender(page);
          await d.getByRole('button', { name: 'פעולות מכרז' }).click();
          await page.getByRole('menuitem', { name: 'העברה לארכיון' }).click();
          await page.getByRole('dialog', { name: 'להעביר את המכרז לארכיון?' }).getByRole('button', { name: 'העברה לארכיון' }).click();
          await expect(d.getByText('בארכיון', { exact: true })).toBeVisible();
        } catch (e) {
          journal(`tender ${tenderId} «${title}» (tender-actions 1.2 cleanup failed: ${(e as Error).message.split('\n')[0]})`);
        }
      }
    }
  });
});
